json assistant_endpoints(){json a=json::array();for(auto pair:{std::pair{"GET","/assistant"},std::pair{"GET","/assistant/setup"},std::pair{"GET","/assistant/explorer"},std::pair{"GET","/assistant/confirmations/{id}"},std::pair{"POST","/assistant/confirmations/{id}/confirm"},std::pair{"POST","/assistant/confirmations/{id}/cancel"},std::pair{"POST","/assistant/requests"},std::pair{"GET","/assistant/requests/{id}"},std::pair{"GET","/assistant/actions/{id}"},std::pair{"POST","/assistant/actions/{id}/undo"}})a.push_back({{"access","assistant.use in token mode; explicit allow_open_access in local open mode"},{"method",pair.first},{"path",pair.second},{"description","Luna query harness. Requires assistant.use in token mode, or explicit local allow_open_access. Supports timer creation (timers.write) and active timer listing (timers.read). Calendar occurrence queries require events.read; one-off creation requires events.write. Action inspection and undo require the matching write permission and ownership. Optional conversation_id continues a caller-scoped 24-hour conversation; omit to start fresh. See GET /assistant/setup for the full integration contract. Undo stops a created timer within 24 hours; later stop/confirm conflicts return 409. POST is synchronous (up to two 45-second provider calls), deduplicated per identity/request_id; GET polls stored results. New ID required to retry failed requests."},{"input",{{"body",pair.first==std::string("POST")?json{{"request_id","phone-001"},{"text","Hello"}}:json(nullptr)}}},{"output",{{"status",200},{"body",pair.second==std::string("/assistant")?json{{"enabled",true},{"version",1},{"tools_enabled",true},{"conversation_support",true}}:json{{"version",1},{"request_id","phone-001"},{"status","completed"},{"message","Hello"},{"resources",json::array()},{"undo_available",false},{"error",nullptr},{"created_at",0}}}}}});for(auto& e:a){if(e["path"]=="/assistant/explorer"){e["description"]="Browser assistant: type queries, continue conversations, confirm/cancel previews and undo actions. Uses browser session authentication and CSRF protection; requires assistant.use. Network recovery resubmits the identical request ID.";e["output"]={{"status",200},{"headers",{{"Content-Type","text/html; charset=utf-8"}}},{"body","HTML assistant conversation page"}};}if(e["path"].get<std::string>().rfind("/assistant/confirmations/",0)==0){e["description"]="Inspect or decide a saved calendar edit/removal preview. Requires assistant.use, events.read and events.write plus ownership. No model call. Confirm executes exact saved change after rechecking snapshot and five-minute expiry. Cancel/superseded proposals cannot execute. Repeated confirmation is idempotent. POST expiry returns 410; conflicting/superseded proposals return 409. See /assistant/setup.";e["input"]["body"]=e["method"]=="POST"?json::object():json(nullptr);e["output"]["body"]={{"version",1},{"status","needs_confirmation"},{"confirmation_id","64-character ID"},{"confirmation_status","pending"},{"confirmation_expires_at","UTC timestamp"},{"preview",{{"operation","calendar.update"},{"scope","event or series"},{"before","event snapshot"},{"after","proposed snapshot, or null for deletion"}}}};}if(e["path"].get<std::string>().rfind("/assistant/actions/",0)==0){e["input"]["body"]=e["method"]=="POST"?json::object():json(nullptr);e["output"]["body"]={{"id","64-character action ID"},{"kind","timers.create"},{"resource","/timers/{id}"},{"status","completed or undone"},{"undo_available",true},{"before_state",nullptr},{"after_state","timer snapshot"},{"undo_state",nullptr},{"created_at","UTC timestamp"},{"undo_until","UTC timestamp"}};}if(e["path"]=="/assistant/setup"){e["description"]="Integration guide: caller permissions, authentication, request/response contract, conversation follow-ups, calendar selection, retries, undo and limits.";e["output"]["body"]=assistant_setup(true,true,Identity{"open","local","open",{}});}}return a;}
